 SELECT root_proc_inst_id_, cast(convert_from(bytes_, ''UTF8'') as jsonb) as txn FROM camunda.act_ge_bytearray WHERE id_ IN ( SELECT \\"Bytearrayid\\" FROM filtered_hiproinst where \\"Bytearrayid\\" is not null ) ) SELECT hiproinst.\\"Case ID\\", pdef.name_ AS \\"Case Type\\", ''Closed'' AS \\"Stage\\", hiproinst.\\"Alert\\", hiproinst.\\"Payer\\", hiproinst.\\"Amount\\", hiproinst.\\"Payee\\", null AS \\"Claimed By\\", null AS \\"Claimed On\\", hiproinst.\\"Created Date\\", ''Closed'' AS \\"Status\\", hiproinst.\\"Closed Date\\", CASE WHEN hiproinst.state_ != ''ACTIVE'' THEN CASE WHEN closedby.assignee_ IS NOT NULL THEN wuser.vcemailid ELSE ''Auto Closed'' END ELSE NULL END AS \\"Closed By\\", hiproinst.\\"Alert Type\\", hiproinst.\\"Address\\", txn.txn -> ''txn'' -> ''attribs'' ->> ''referenceNumber'' AS \\"RRN\\", txn.txn -> ''txn'' -> ''attribs'' ->> ''invoice'' AS \\"ORN\\", CASE WHEN txn.txn->''txn''->>''type'' = ''REFUND'' THEN txn.txn->''observations''->''payerVPA''->''account''->''customer''->>''customerName'' ELSE txn.txn->''observations''->''payeeVPA''->''account''->''customer''->>''customerName'' END AS \\"Merchant Name\\", txn.txn -> ''txn'' ->> ''id'' AS \\"Transaction ID\\", txn.txn -> ''txn'' ->> ''type'' AS \\"Transaction Type\\", txn.txn -> ''payer'' -> ''attribs'' -> ''identity'' ->> ''email'' AS \\"Payer Email\\", txn.txn -> ''payer'' -> ''attribs'' -> ''device'' ->> ''mobilenum'' AS \\"Payer Mobile Num\\", txn.txn -> ''payee'' -> ''attribs'' -> ''identity'' ->> ''email'' AS \\"Payee Email\\", txn.txn -> ''payee'' -> ''attribs'' -> ''device'' ->> ''mobilenum'' AS \\"Payee Mobile Num\\", txn.txn -> ''observations'' -> ''customer'' ->> ''vccustomername'' AS \\"Account Name\\" FROM filtered_hiproinst hiproinst JOIN camunda.act_re_procdef pdef ON pdef.id_ = hiproinst.proc_def_id_ LEFT JOIN ranked_closedby closedby ON closedby.proc_inst_id_ = hiproinst.proc_inst_id_ AND closedby.rn = 1 LEFT JOIN ui.webuser wuser ON wuser.iuserid = CAST(closedby.assign