        "Unclaimed": " WITH filtered_hiproinst AS ( SELECT hiproinst.proc_def_id_, hiproinst.tenant_id_, hiproinst.state_, hiproinst.end_time_ as \\"Closed Date\\", hiproinst.start_time_ AS \\"Created Date\\", hiproinst.proc_inst_id_, rutask.assignee_, rutask.name_, MAX( CASE WHEN vars.name_ = ''payer'' THEN vars.text_ END ) AS \\"Payer\\", MAX( CASE WHEN vars.name_ = ''payee'' THEN vars.text_ END ) AS \\"Payee\\", MAX( CASE WHEN vars.name_ = ''TransactionAmount'' THEN vars.double_ / 100 END ) AS \\"Amount\\", MAX( CASE WHEN vars.name_ = ''TicketID'' THEN vars.long_ END ) AS \\"Case ID\\", MAX( CASE WHEN vars.name_ = ''Alert'' THEN vars.text_ END ) AS \\"Alert\\", MAX( CASE WHEN vars.name_ = ''basedon'' THEN vars.text_ END ) AS \\"Alert Type\\", MAX( CASE WHEN vars.name_ = ''address'' THEN vars.text_ END ) AS \\"Address\\", MAX( CASE WHEN vars.name_ = ''Transaction'' THEN vars.bytearray_id_ END ) AS \\"Bytearrayid\\" FROM camunda.act_hi_procinst hiproinst JOIN camunda.act_ru_task rutask on rutask.proc_inst_id_ = hiproinst.proc_inst_id_ and rutask.assignee_ is null JOIN camunda.act_hi_varinst vars ON vars.proc_inst_id_ = hiproinst.proc_inst_id_ and vars.name_ in ( ''payer'', ''payee'', ''TransactionAmount'', ''TicketID'', ''Alert'', ''basedon'', ''address'', ''Transaction'' ) WHERE hiproinst.start_time_ >= :StartDate AND hiproinst.start_time_ <= :EndDate AND hiproinst.state_ = ''ACTIVE'' AND hiproinst.proc_def_key_ = :CaseType AND hiproinst.tenant_id_ = :tenantidstr GROUP BY 1, 2, 3, 4, 5, 6, 7, 8 ORDER BY hiproinst.start_time_ LIMIT 30000 ), bytearray_cte AS ( SELECT root_proc_inst_id_, cast(convert_from(bytes_, ''UTF8'') as jsonb) as txn FROM camunda.act_ge_bytearray WHERE id_ IN ( SELECT \\"Bytearrayid\\" FROM filtered_hiproinst where \\"Bytearrayid\\" is not null ) ) SELECT hiproinst.\\"Case ID\\", pdef.name_ AS \\"Case Type\\", CASE WHEN hiproinst.state_ = ''ACTIVE'' THEN hiproinst.name_ ELSE ''Closed'' END AS \\"Stage\\", hiproinst.\\"Alert\\", hiproinst.\\"Payer\\", hiproinst.\\"Amount\\", hiproinst.\\"Payee\\", null AS \\"Claimed By\\", null AS \\"Claimed On\\", hiproinst.\\"Created Date\\", CASE WHEN hiproinst.state_ != ''ACTIVE'' THEN ''Closed'' WHEN hiproinst.assignee_ IS NOT NULL THEN ''Claimed'' ELSE ''Unclaimed'' END AS \\"Status\\", hiproinst.\\"Closed Date\\", null AS \\"Closed By\\", hiproinst.\\"Alert Type\\", hiproinst.\\"Address\\", txn.txn -> ''txn'' -> ''attribs'' ->> ''referenceNumber'' AS \\"RRN\\", txn.txn -> ''txn'' -> ''attribs'' ->> ''invoice'' AS \\"ORN\\", CASE WHEN txn.txn->''txn''->>''type'' = ''REFUND'' THEN txn.txn->''observations''->''payerVPA''->''account''->''customer''->>''customerName'' ELSE txn.txn->''observations''->''payeeVPA''->''account''->''customer''->>''customerName'' END AS \\"Merchant Name\\", txn.txn -> ''txn'' ->> ''id'' AS \\"Transaction ID\\", txn.txn -> ''txn'' ->> ''type'' AS \\"Transaction Type\\", txn.txn -> ''payer'' -> ''attribs'' -> ''identity'' ->> ''email'' AS \\"Payer Email\\", txn.txn -> ''payer'' -> ''attribs'' -> ''device'' ->> ''mobilenum'' AS \\"Payer Mobile Num\\", txn.txn -> ''payee'' -> ''attribs'' -> ''identity'' ->> ''email'' AS \\"Payee Email\\", txn.txn -> ''payee'' -> ''attribs'' -> ''device'' ->> ''mobilenum'' AS \\"Payee Mobile Num\\", txn.txn -> ''observations'' -> ''customer'' ->> ''vccustomername'' AS \\"Account Name\\" FROM filtered_hiproinst hiproinst JOIN camunda.act_re_procdef pdef ON pdef.id_ = hiproinst.proc_def_id_ JOIN bytearray_cte txn ON txn.root_proc_inst_id_ = hiproinst.proc_inst_id_;",
        "All": " WITH filtered_hiproinst AS ( SELECT hiproinst.proc_def_id_, hiproinst.tenant_id_, hiproinst.state_, hiproinst.end_time_ as \\"Closed Date\\", hiproinst.start_time_ AS \\"Created Date\\", hiproinst.proc_inst_id_, MAX( CASE WHEN vars.name_ = ''payer'' THEN vars.text_ END ) AS \\"Payer\\", MAX( CASE WHEN vars.name_ = ''payee'' THEN vars.text_ END ) AS \\"Payee\\", MAX( CASE WHEN vars.name_ = ''TransactionAmount'' THEN vars.double_ / 100 END ) AS \\"Amount\\", MAX( CASE WHEN vars.name_ = ''TicketID'' THEN vars.long_ END ) AS \\"Case ID\\", MAX( CASE WHEN vars.name_ = ''Alert'' THEN vars.text_ END ) AS \\"Alert\\", MAX( CASE WHEN vars.name_ = ''basedon'' THEN vars.text_ END ) AS \\"Alert Type\\", MAX( CASE WHEN vars.name_ = ''address'' THEN vars.text_ END ) AS \\"Address\\", MAX( CASE WHEN vars.name_ = ''Transaction'' THEN vars.bytearray_id_ END ) AS \\"Bytearrayid\\" FROM camunda.act_hi_procinst hiproinst JOIN camunda.act_hi_varinst vars ON vars.proc_inst_id_ = hiproinst.proc_inst_id_ and name_ in ( ''payer'', ''payee'', ''TransactionAmount'', ''TicketID'', ''Alert'', ''basedon'', ''address'', ''Transaction'' ) WHERE hiproinst.start_time_ >= :StartDate AND hiproinst.start_time_ <= :EndDate AND hiproinst.state_ != ''EXTERNALLY_TERMINATED'' AND hiproinst.proc_def_key_ = :CaseType AND hiproinst.tenant_id_ = :tenantidstr GROUP BY 1, 2, 3, 4, 5, 6 ORDER BY hiproinst.start_time_ LIMIT 30000 ), ranked_closedby AS ( SELECT proc_inst_id_, assignee_, ROW_NUMBER() OVER ( PARTITION BY proc_inst_id_ ORDER BY end_time_ DESC ) AS rn FROM camunda.act_hi_taskinst WHERE proc_inst_id_ IN ( SELECT proc_inst_id_ FROM filtered_hiproinst where state_ = ''COMPLETED'' ) ), ranked_oplog AS ( SELECT proc_inst_id_, time_, ROW_NUMBER() OVER ( PARTITION BY proc_inst_id_ ORDER BY time_ DESC ) AS rn FROM camunda.act_hi_detail WHERE name_ = ''userActivity'' AND proc_inst_id_ IN ( SELECT proc_inst_id_ FROM filtered_hiproinst where state_ = ''ACTIVE'' ) ), task_cte AS ( SELECT proc_inst_id_, assignee_, name_ FROM camunda.act_hi_taskinst WHERE proc_inst_id_ IN ( SELECT proc_inst_id_ FROM filtered_hiproinst where state_ = ''ACTIVE'' ) ), bytearray_cte AS ( SELECT root_proc_inst_id_, cast(convert_from(bytes_, ''UTF8'') as jsonb) as txn FROM camunda.act_ge_bytearray WHERE id_ IN ( SELECT \\"Bytearrayid\\" FROM filtered_hiproinst where \\"Bytearrayid\\" is not null ) ) SELECT hiproinst.\\"Case ID\\", pdef.name_ AS \\"Case Type\\", CASE WHEN hiproinst.state_ = ''ACTIVE'' THEN task.name_ ELSE ''Closed'' END AS \\"Stage\\", hiproinst.\\"Alert\\", hiproinst.\\"Payer\\", hiproinst.\\"Amount\\", hiproinst.\\"Payee\\", wu.vcemailid AS \\"Claimed By\\", CASE WHEN task.assignee_ IS NOT NULL THEN oplog.time_ ELSE NULL END AS \\"Claimed On\\", hiproinst.\\"Created Date\\", CASE WHEN hiproinst.state_ != ''ACTIVE'' THEN ''Closed'' WHEN task.assignee_ IS NOT NULL THEN ''Claimed'' ELSE ''Unclaimed'' END AS \\"Status\\", hiproinst.\\"Closed Date\\", CASE WHEN hiproinst.state_ != ''ACTIVE'' THEN CASE WHEN closedby.assignee_ IS NOT NULL THEN wuser.vcemailid ELSE ''Auto Closed'' END ELSE NULL END AS \\"Closed By\\", hiproinst.\\"Alert Type\\", hiproinst.\\"Address\\", txn.txn -> ''txn'' -> ''attribs'' ->> ''referenceNumber'' AS \\"RRN\\", txn.txn -> ''txn'' -> ''attribs'' ->> ''invoice'' AS \\"ORN\\", CASE WHEN txn.txn->''txn''->>''type'' = ''REFUND'' THEN txn.txn->''observations''->''payerVPA''->''account''->''customer''->>''customerName'' ELSE txn.txn->''observations''->''payeeVPA''->''account''->''customer''->>''customerName'' END AS \\"Merchant Name\\", txn.txn -> ''txn'' ->> ''id'' AS \\"Transaction ID\\", txn.txn -> ''txn'' ->> ''type'' AS \\"Transaction Type\\", txn.txn -> ''payer'' -> ''attribs'' -> ''identity'' ->> ''email'' AS \\"Payer Email\\", txn.txn -> ''payer'' -> ''attribs'' -> ''device'' ->> ''mobilenum'' AS \\"Payer Mobile Num\\", txn.txn -> ''payee'' -> ''attribs'' -> ''identity'' ->> ''email'' AS \\"Payee Email\\", txn.txn -> ''payee'' -> ''attribs'' -> ''device'' ->> ''mobilenum'' AS \\"Payee Mobile Num\\", txn.txn -> ''observations'' -> ''customer'' ->> ''vccustomername'' AS \\"Account Name\\" FROM filtered_hiproinst hiproinst JOIN camunda.act_re_procdef pdef ON pdef.id_ = hiproinst.proc_def_id_ LEFT JOIN ranked_closedby closedby ON closedby.proc_inst_id_ = hiproinst.proc_inst_id_ AND closedby.rn = 1 LEFT JOIN task_cte task ON task.proc_inst_id_ = hiproinst.proc_inst_id_ LEFT JOIN ui.webuser wu ON wu.iuserid = CAST(task.assignee_ AS INTEGER) LEFT JOIN ranked_oplog oplog ON oplog.proc_inst_id_ = task.proc_inst_id_ AND oplog.rn = 1 LEFT JOIN ui.webuser wuser ON wuser.iuserid = CAST(closedby.assignee_ AS INTEGER) JOIN bytearray_cte txn ON txn.root_proc_inst_id_ = hiproinst.proc_inst_id_;",
